fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var sum = 0;
    var i = 1;
    while i <= 40 {
        sum = sum + i;
        i = i + 1;
    }

    var prod = 1;
    var j = 1;
    while j <= 8 {
        prod = prod * j;
        j = j + 1;
    }

    let output = sum.to_text().concat(other: " ").concat(other: prod.to_text());
    io.write(text: output)?;
    return Ok(unit);
}

fn sum_up_to(n: Int) -> Int {
    var total = 0;
    var i = 1;
    while i <= n {
        total = total + i;
        i = i + 1;
    }
    total
}

fn print_sum(io: Io, n: Int) -> Result<Unit, Error> uses {Io.write} {
    let total = sum_up_to(n: n);
    let line = n.to_text().concat(other: ": ").concat(other: total.to_text()).concat(other: "\n");
    io.write(text: line)?;
    return Ok(unit);
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    print_sum(io: io, n: 12)?;
    print_sum(io: io, n: 30)?;
    print_sum(io: io, n: 7)?;
    return Ok(unit);
}
